"""Assemble the measured test report and lifecycle receipts without changing selections."""
from pathlib import Path
import hashlib,json,shutil,statistics
ROOT=Path(__file__).resolve().parents[2]
OUT=Path('/home/peter_aetherlabs_live/jep-full-data-test-launch-20261108')
DEST=ROOT/'training_outputs/full_data_prompt_20261108'
result=json.loads((DEST/'test_and_validation.json').read_text())
complete=json.loads((OUT/'test-evaluation-complete.json').read_text())
assert len(result['per_trial'])==15
assert len(complete['workers'])==2
assert sum(len(w['cloud_proofs']) for w in complete['workers'])==45
assert all(p['verified'] for w in complete['workers'] for p in w['cloud_proofs'])
cleanup={'workers':{str(w):json.loads((OUT/f'cleanup-eval{w}.json').read_text()) for w in (1,2)},'template_snapshot':json.loads((OUT/'cleanup-test-template.json').read_text())}
assert all(c['instance_deleted'] and c['disk_deleted'] for c in cleanup['workers'].values())
assert cleanup['template_snapshot']['verified_deleted']
(DEST/'test-cleanup.json').write_text(json.dumps(cleanup,indent=2)+'\n')
for source,target in [('test-evaluation-complete.json','test-publication-receipts.json'),('payload-cloud-refs.json','test-input-publication.json'),('evaluation-source.json','test-source.json')]:
 shutil.copyfile(OUT/source,DEST/target)
allocations={str(w):json.loads((OUT/f'allocation-eval{w}.json').read_text()) for w in (1,2)}
(DEST/'test-allocations.json').write_text(json.dumps(allocations,indent=2)+'\n')
for w in (1,2):shutil.copyfile(OUT/f'runtime-eval{w}.txt',DEST/f'test-runtime-worker{w}.txt')
records=[r for w in complete['workers'] for r in w['native_completion']['records']]
scoring={m['trial_id']:m['scoring_seconds'] for m in result['per_trial']}
profile={'test_captures':15,'test_comparisons_per_checkpoint':2430,'native_total_seconds':sum(r['seconds'] for r in records),'scoring_including_model_load_seconds':sum(scoring.values()),'mean_native_seconds_per_checkpoint':statistics.mean(r['seconds'] for r in records),'mean_scoring_including_model_load_seconds_per_checkpoint':statistics.mean(scoring.values()),'interpretation':'Difference includes native run preparation, immutable artifact handling and stage orchestration; scoring includes model loading, input verification and tokenization. This measurement does not isolate pure GPU forward time.'}
profile['outside_scoring_seconds']=profile['native_total_seconds']-profile['scoring_including_model_load_seconds']
profile['outside_scoring_fraction']=profile['outside_scoring_seconds']/profile['native_total_seconds']
(DEST/'test-timing-profile.json').write_text(json.dumps(profile,indent=2)+'\n')
lines=['# Full-data prompt experiment: validation and test','','All 15 LoRA fits and all 15 frozen-checkpoint test evaluations are complete. Values are mean ± sample SD across the same five seeds. Patience remained 1. Checkpoints were selected using validation before test inference.','','| Prompt arm | Validation Spearman | Test Spearman |','| --- | ---: | ---: |']
for s in result['summary']:lines.append(f'| {s["arm"]} | {s["validation_mean"]:.6f} ± {s["validation_sd"]:.6f} | {s["test_mean"]:.6f} ± {s["test_sd"]:.6f} |')
lines+=['','A places the condition first. B moves the same instruction after the passage. C uses the CASE-inspired condition-target formulation. Validation has 1,576 comparisons; test has 2,430 comparisons in 1,222 source groups.','','[Paired comparisons and bootstrap intervals](test-results.md) · [Per-fit validation/test scores](test_and_validation.csv) · [Full statistics](test_and_validation.json)','','The test partition was examined in earlier work. These are exploratory comparisons; test scores did not choose checkpoints or extend training. The 10,000-draw shared source-group bootstrap conditions on the trained checkpoints. Seed variation is reported separately.','','## Publication and resource cleanup','','Training produced 77 checkpoint archives (35,921,745,920 bytes). All archives and three input files passed independent cloud byte verification before the original training VMs and disks were deleted.','','The inference-only evaluation restored the 15 exact selected model hashes. Each worker replayed one validation score exactly before scoring test. Predictions, timing and native run references were uploaded asynchronously through VIPER Cloud. All 45 test artifacts were independently downloaded and SHA-256 verified, including ordered row identities, targets and frozen model/test hashes. Both evaluation VMs, their disks and the temporary evaluation snapshot were deleted after verification. Historical source resources were preserved.','','- [Frozen checkpoint selections](frozen-selections.json)','- [Training archive hashes and cloud references](cloud-archive-inventory.json)','- [Training cleanup receipts](cleanup.json)','- [Test publication and verification receipts](test-publication-receipts.json)','- [Test input publication references](test-input-publication.json)','- [Test allocations](test-allocations.json)','- [Test cleanup receipts](test-cleanup.json)','- [Measured evaluation timing](test-timing-profile.json)','- [Controller access receipts](controller-access.json)','- [Controller metadata authentication preflight](controller-metadata-preflight.json)','- [Controller failure diagnosis and repair](../../plans/full_data_prompt_20261107/controller-repair-20261108/README.md)','','## Publishing progress','','The durable CPU reporter checks every 30 seconds and publishes newly measured scores to the established [GitHub tracker](https://github.com/pvd232/JEP/blob/monitor/full-data-prompt-20261107/plans/full_data_prompt_20261107/live-status.md). It distinguishes sealed predictions from independently verified cloud bytes. The [execution procedure](../../scripts/full_data_prompt_20261107/README.md) and reporter are committed with this experiment.','','Two evaluation-launch API errors were repaired before any test scoring. The final inference source is `'+result['source_commit']+'`. Validation replay matched both saved scores exactly. The current evaluator reloads the backbone and starts a native run for each checkpoint; the timing profile measures this overhead rather than treating total elapsed time as GPU forward time.','','The controller uses its attached service account with automatic credential refresh and permanent project-wide Owner and IAP access on Mantra, plus Storage Admin on the VIPER bucket, as explicitly requested.','','Training execution source: `83467f756d1d10e9c1f3183d9242cea4424e1ce4`. Scientific training source: `9b163a100362580f99722eecc63895420ecec3b1`. Protocol SHA-256: `0aee2f8aece3e89ff12223fe40a54fb632305339f240475362212c432fd68a11`.','','The original frozen-selection release records retain their pre-evaluation timestamps and unopened-test flags. The completed test release is recorded separately in the test receipts above.','']
text='\n'.join(lines)
b=result['contrasts']['B-A'];interval=b['test_group_interval_95']
assert all(c['test_group_interval_95'][0]<=0<=c['test_group_interval_95'][1] for c in result['contrasts'].values())
text=text.replace('A places the condition first.', f'B has the highest mean test score, {b["mean"]:+.6f} above A. Its conditional 95% source-group bootstrap interval is [{interval[0]:+.6f}, {interval[1]:+.6f}]. All three paired intervals include zero, so this study does not establish a clear prompt winner. C has the highest mean validation score.\n\nA places the condition first.')
text=text.replace('Two evaluation-launch API errors were repaired before any test scoring.', f'Across all 15 test captures, mean elapsed time was {profile["mean_native_seconds_per_checkpoint"]:.2f} seconds per checkpoint: {profile["mean_scoring_including_model_load_seconds_per_checkpoint"]:.2f} seconds for scoring including model loading, and {profile["outside_scoring_seconds"]/15:.2f} seconds outside scoring ({100*profile["outside_scoring_fraction"]:.1f}%). This is measurable orchestration and artifact overhead.\n\nTwo evaluation-launch API errors were repaired before any test scoring.')
(DEST/'README.md').write_text(text)
print(json.dumps({'scores':result['summary'],'contrasts':result['contrasts'],'timing':profile},indent=2))
